<div class="mb-6"><p class="text-sm font-medium text-blue-600">Asistencia</p><h1 class="text-2xl font-bold">Horarios y sesiones</h1><p class="mt-1 text-sm text-slate-500">Asigne una jornada a cada persona o sesiones específicas a docentes por curso.</p></div>
<section class="grid gap-5 lg:grid-cols-3"><article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h2 class="font-semibold">Asignar jornada individual</h2><form method="post" action="index.php?url=horarios_guardar" class="mt-4 space-y-3"><?= campoCsrf() ?><input type="hidden" name="entidad" value="jornada_persona"><label class="form-label">Persona<select required name="id_persona" class="form-input"><option value="">Seleccione</option><?php foreach($personas as $p): ?><option value="<?= $p['id_persona'] ?>"><?= htmlspecialchars($p['nombre'].' · '.$p['perfiles']) ?></option><?php endforeach; ?></select></label><label class="form-label">Jornada<select required name="id_jornada" class="form-input"><option value="">Seleccione</option><?php foreach($jornadas as $j): ?><option value="<?= $j['id_jornada'] ?>"><?= htmlspecialchars($j['nombre'].' · '.$j['hora_entrada'].'-'.$j['hora_salida']) ?></option><?php endforeach; ?></select></label><label class="form-label">Desde<input required type="date" name="fecha_inicio" value="<?= date('Y-m-d') ?>" class="form-input"></label><label class="form-label">Hasta <span class="font-normal text-slate-400">(opcional)</span><input type="date" name="fecha_fin" class="form-input"></label><button class="w-full rounded-xl bg-blue-600 py-2 text-sm font-semibold text-white">Asignar jornada</button></form></article><article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h2 class="font-semibold">Nueva asignatura</h2><form method="post" action="index.php?url=horarios_guardar" class="mt-4 flex gap-2"><?= campoCsrf() ?><input type="hidden" name="entidad" value="asignatura"><input required name="nombre" class="form-input mt-0" placeholder="Matemática"><button class="rounded-xl bg-blue-600 px-3 text-sm font-semibold text-white">Agregar</button></form><div class="mt-4 max-h-56 space-y-2 overflow-y-auto"><?php foreach($asignaturas as $a): ?><div class="rounded-xl bg-slate-50 p-2 text-sm"><?= htmlspecialchars($a['nombre']) ?></div><?php endforeach; ?></div></article><article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h2 class="font-semibold">Sesión docente por curso</h2><form method="post" action="index.php?url=horarios_guardar" class="mt-4 grid gap-3"><?= campoCsrf() ?><input type="hidden" name="entidad" value="sesion"><select required name="id_vinculo" class="form-input mt-0"><option value="">Docente</option><?php foreach($docentes as $d): ?><option value="<?= $d['id_vinculo'] ?>"><?= htmlspecialchars($d['nombre']) ?></option><?php endforeach; ?></select><select required name="id_periodo_academico" class="form-input mt-0"><option value="">Período</option><?php foreach($periodos as $p): ?><option value="<?= $p['id_periodo_academico'] ?>"><?= htmlspecialchars($p['nombre']) ?></option><?php endforeach; ?></select><select required name="id_seccion" class="form-input mt-0"><option value="">Sección</option><?php foreach($secciones as $s): ?><option value="<?= $s['id_seccion'] ?>"><?= htmlspecialchars($s['nombre']) ?></option><?php endforeach; ?></select><select required name="id_asignatura" class="form-input mt-0"><option value="">Asignatura</option><?php foreach($asignaturas as $a): ?><option value="<?= $a['id_asignatura'] ?>"><?= htmlspecialchars($a['nombre']) ?></option><?php endforeach; ?></select><select required name="dia_semana" class="form-input mt-0"><option value="1">Lunes</option><option value="2">Martes</option><option value="3">Miércoles</option><option value="4">Jueves</option><option value="5">Viernes</option><option value="6">Sábado</option></select><div class="grid grid-cols-3 gap-2"><input required type="time" name="hora_inicio" class="form-input mt-0"><input required type="time" name="hora_fin" class="form-input mt-0"><input required type="number" min="0" name="tolerancia_minutos" value="10" class="form-input mt-0"></div><button class="rounded-xl bg-violet-600 py-2 text-sm font-semibold text-white">Programar sesión</button></form></article></section>
<section class="mt-6 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="border-b border-slate-100 px-5 py-4"><h2 class="font-semibold">Sesiones programadas</h2><p class="text-sm text-slate-500">Activa o desactiva sesiones sin perder su historial.</p></div><div class="overflow-x-auto"><table data-datatable data-page-options="5,10,25,50" class="min-w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="px-4 py-3">Docente</th><th class="px-4 py-3">Curso</th><th class="px-4 py-3">Horario</th><th class="px-4 py-3">Nivel / grado / sección</th><th class="px-4 py-3">Estado</th><th class="no-sort px-4 py-3 text-right">Acciones</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach($cargas as $c): ?><tr><td class="px-4 py-3 font-medium"><?= htmlspecialchars($c['docente']) ?></td><td class="px-4 py-3"><?= htmlspecialchars($c['asignatura']) ?></td><td class="px-4 py-3 text-slate-600"><?= htmlspecialchars(['','Lun','Mar','Mié','Jue','Vie','Sáb','Dom'][$c['dia_semana']].' · '.$c['hora_inicio'].'-'.$c['hora_fin']) ?></td><td class="px-4 py-3"><?= htmlspecialchars($c['seccion']) ?></td><td class="px-4 py-3"><span class="inline-flex rounded-full px-2.5 py-1 text-xs font-semibold <?= $c['estado']==='ACTIVO'?'bg-emerald-100 text-emerald-700':'bg-slate-200 text-slate-600' ?>"><?= htmlspecialchars($c['estado']) ?></span></td><td class="px-4 py-3 text-right"><div class="inline-flex gap-2"><?php if($c['estado']==='ACTIVO'): ?><button type="button" onclick="editarSesion(this)" data-id="<?= $c['id_carga'] ?>" data-vinculo="<?= $c['id_vinculo'] ?>" data-periodo="<?= $c['id_periodo_academico'] ?>" data-seccion="<?= $c['id_seccion'] ?>" data-asignatura="<?= $c['id_asignatura'] ?>" data-dia="<?= $c['dia_semana'] ?>" data-inicio="<?= $c['hora_inicio'] ?>" data-fin="<?= $c['hora_fin'] ?>" data-tolerancia="<?= $c['tolerancia_minutos'] ?>" class="inline-flex h-10 w-10 items-center justify-center rounded-lg bg-amber-100 text-amber-800 hover:bg-amber-200" title="Editar sesión"><i class="bi bi-pencil-square"></i></button><form method="post" action="index.php?url=horarios_guardar" class="inline-flex"><?= campoCsrf() ?><input type="hidden" name="entidad" value="sesion_desactivar"><input type="hidden" name="id_carga" value="<?= $c['id_carga'] ?>"><button class="inline-flex h-10 w-10 items-center justify-center rounded-lg bg-red-100 text-red-700 hover:bg-red-200" title="Desactivar sesión"><i class="bi bi-pause-circle"></i></button></form><?php else: ?><form method="post" action="index.php?url=horarios_guardar" class="inline-flex"><?= campoCsrf() ?><input type="hidden" name="entidad" value="sesion_activar"><input type="hidden" name="id_carga" value="<?= $c['id_carga'] ?>"><button class="inline-flex h-10 w-10 items-center justify-center rounded-lg bg-emerald-100 text-emerald-700 hover:bg-emerald-200" title="Activar sesión"><i class="bi bi-play-circle"></i></button></form><?php endif; ?></div></td></tr><?php endforeach; ?><?php if(!$cargas): ?><tr><td colspan="6" class="px-5 py-10 text-center text-slate-500">No hay sesiones programadas.</td></tr><?php endif; ?></tbody></table></div></section>
<div id="modal-editar-sesion" class="fixed inset-0 z-[60] hidden overflow-y-auto bg-slate-900/45 p-4"><div class="mx-auto mt-8 max-w-lg rounded-2xl bg-white p-6 shadow-2xl"><h2 class="text-lg font-bold">Editar sesión programada</h2><form method="post" action="index.php?url=horarios_guardar" class="mt-4 grid gap-3"><?= campoCsrf() ?><input type="hidden" name="entidad" value="sesion_actualizar"><input id="es-id" type="hidden" name="id_carga"><label class="form-label">Docente<select id="es-vinculo" required name="id_vinculo" class="form-input"><?php foreach($docentes as $d): ?><option value="<?= $d['id_vinculo'] ?>"><?= htmlspecialchars($d['nombre']) ?></option><?php endforeach; ?></select></label><div class="grid gap-3 sm:grid-cols-2"><label class="form-label">Período<select id="es-periodo" required name="id_periodo_academico" class="form-input"><?php foreach($periodos as $p): ?><option value="<?= $p['id_periodo_academico'] ?>"><?= htmlspecialchars($p['nombre']) ?></option><?php endforeach; ?></select></label><label class="form-label">Sección<select id="es-seccion" required name="id_seccion" class="form-input"><?php foreach($secciones as $s): ?><option value="<?= $s['id_seccion'] ?>"><?= htmlspecialchars($s['nombre']) ?></option><?php endforeach; ?></select></label></div><div class="grid gap-3 sm:grid-cols-2"><label class="form-label">Asignatura<select id="es-asignatura" required name="id_asignatura" class="form-input"><?php foreach($asignaturas as $a): ?><option value="<?= $a['id_asignatura'] ?>"><?= htmlspecialchars($a['nombre']) ?></option><?php endforeach; ?></select></label><label class="form-label">Día<select id="es-dia" required name="dia_semana" class="form-input"><option value="1">Lunes</option><option value="2">Martes</option><option value="3">Miércoles</option><option value="4">Jueves</option><option value="5">Viernes</option><option value="6">Sábado</option></select></label></div><div class="grid grid-cols-3 gap-2"><label class="form-label">Inicio<input id="es-inicio" required type="time" name="hora_inicio" class="form-input"></label><label class="form-label">Fin<input id="es-fin" required type="time" name="hora_fin" class="form-input"></label><label class="form-label">Tolerancia<input id="es-tolerancia" required type="number" min="0" name="tolerancia_minutos" class="form-input"></label></div><div class="mt-2 flex justify-end gap-2"><button type="button" onclick="document.getElementById('modal-editar-sesion').classList.add('hidden')" class="rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-600">Cancelar</button><button class="rounded-xl bg-amber-400 px-4 py-2 text-sm font-semibold text-amber-950">Guardar cambios</button></div></form></div></div><script>function editarSesion(b){['id','vinculo','periodo','seccion','asignatura','dia','inicio','fin','tolerancia'].forEach(c=>document.getElementById('es-'+c).value=b.dataset[c]);document.getElementById('modal-editar-sesion').classList.remove('hidden');}</script>
